// CRIS v2.3 — Mensaje CONTACTO_2 — selección aleatoria 3 opciones
const item = $input.first().json;
function toTitleCase(s) { return String(s||'').toLowerCase().replace(/\b\w/g, c => c.toUpperCase()); }
const nombre  = toTitleCase(item.nombre_cliente || 'estimado/a cliente');
const modelo  = toTitleCase(item.modelo || 'su vehiculo');
const marca   = (item.marca || 'KIA').toUpperCase();
const marcaNombre = marca === 'HYUNDAI' ? 'Hyundai' : 'KIA';
const servicioMarca = item.servicio_marca || (marca === 'HYUNDAI' ? 'My Hyundai Link' : 'Telemetría KIA');
const telefonoWa = item.telefono.startsWith('593') ? item.telefono : ('593' + item.telefono.replace(/^0/, ''));

function applyVars(t) {
  return t
    .replace(/\{nombre_cliente\}/g, nombre)
    .replace(/\{modelo\}/g, modelo)
    .replace(/\{marca\}/g, marcaNombre)
    .replace(/\{servicio_marca\}/g, servicioMarca)
    .replace(/NOMBRE/g, nombre)
    .replace(/MODELO/g, modelo);
}

let opciones = [];
try {
  const raw = item.mensajes_intento;
  if (Array.isArray(raw)) opciones = raw;
  else if (typeof raw === 'string' && raw.startsWith('[')) opciones = JSON.parse(raw);
} catch(e) {}

let msgRaw = '';
if (opciones.length > 0) {
  msgRaw = opciones[Math.floor(Math.random() * opciones.length)];
} else {
  const single = String(item.mensaje_intento_2 || '');
  if (single.length > 10) msgRaw = single;
}

let mensaje = msgRaw ? applyVars(msgRaw) : '';

if (!mensaje) {
  const fb = {
    KIA: [
      `¡Hola ${nombre}! 🤝\nSoy Cris nuevamente y quería saber si tuviste oportunidad de revisar mi mensaje anterior.\nEn menos de 5 minutos podemos mostrarte cómo aprovechar funcionalidades de seguridad y conectividad disponibles desde la aplicación oficial de KIA.\n¿Te interesa conocerlas?\n✅ Sí, quiero saber más\n❌ No por el momento`,
