  };
  msgCierre = fallbacks[marca] ||
    `¡Hola ${nombre}! 🤝\nCris por aquí nuevamente. 😊\nSi en algún momento deseas conocer más sobre el servicio de conectividad y seguridad para tu ${modelo}, estaré disponible para ayudarte. ¡Que disfrutes tu vehículo! 🚗 📲`;
}


return [{json: {
